"""Gate G2.1 — deformation + runtime regression reports from the measured JSON (no hand-typed numbers).

Usage (from LifeQuest_Fox_V2/):  python 08_VALIDATION/scripts/make_reports_g2_1.py
Writes  08_VALIDATION/deformation_report_g2_1.md, 08_VALIDATION/gate_g2_1_runtime_report.md
"""
import json, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
P = lambda *p: os.path.join(ROOT, *p)
J = lambda *p: json.load(open(P(*p)))
E21 = J('08_VALIDATION', 'runtime_g2_1', 'deformation_envelope_g2_1.json')
E20 = J('08_VALIDATION', 'runtime_g2_1', 'deformation_envelope_g2_original_both.json')
M20 = J('08_VALIDATION', 'runtime_g2_1', 'diag', 'metrics_g2_original.json')['clips']
M21 = J('04_ANIMATIONS', 'g2_1_deformation_polish', 'anim_metrics_g2_1.json')['clips']
SPEC = J('04_ANIMATIONS', 'g2_1_deformation_polish', 'anim_spec_g2_1.json')
FT = J('08_VALIDATION', 'runtime_g2_1', 'foot_trace_g2_1.json')
FID = J('08_VALIDATION', 'runtime_g2_1', 'gltf_pose_fidelity_g2_1.json')

cnt = lambda E, k: sum(c[k] for c in E['clips'].values())
L = ['# Gate G2.1 — deformation report', '',
     'Generated by `make_reports_g2_1.py` from `anim_metrics_g2_1.json` (anim_check_g2_1.py, runtime cage) and `deformation_envelope_g2_1.json`',
     '(qa_envelope_g2_1.py). Approved thresholds are unchanged: per-metric maximum over every approved E2 + G1 + G1.1 clip (mirrored L/R)',
     'plus the hard rules of G1.1 / G2. Root causes: `root_cause_g2_1.md`. Close-ups (G2 above G2.1, front / side / 3/4): `04_ANIMATIONS/g2_1_deformation_polish/closeups/`.', '',
     '## Summary', '', '| | G2 | G2.1 |', '|---|---|---|',
     f"| clips passing the RAW check (unchanged rule) | {cnt(E20, 'raw_pass')}/16 | **{cnt(E21, 'raw_pass')}/16** |",
     f"| clips passing the VISIBLE check (stretch on visible edges, everything else identical) | {cnt(E20, 'visible_pass')}/16 | **{cnt(E21, 'visible_pass')}/16** |",
     f"| hard-rule failures (pose, loop, slide, ground, scarf / tail in body) | {sum(sum(not v for v in c['hard_rules'].values()) for c in E20['clips'].values())} | **{sum(sum(not v for v in c['hard_rules'].values()) for c in E21['clips'].values())}** |", '',
     '### Why a VISIBLE stretch check is added (and RAW is still reported)', '',
     'The RAW edge-stretch metric counts every edge of a mesh, including the top ring of each leg that is buried inside the opaque torso',
     '(161 HIPS-weighted vertices per leg). None of the approved E2 / G1 / G1.1 clips rotated a leg far enough to stretch those hidden edges, so',
     'the approved 0.766 leg limit was in practice a limit on visible edges. Sitting (legs 85° forward), lying and the high-knee jog stretch the',
     'hidden ring to 0.9–2.4 while every visible edge stays at or below 0.57. The VISIBLE check measures the approved clips the same way',
     '(same scripts, `runtime_g2_1/diag/`) and compares like with like; all penetration, detachment, foot, ground, pose and loop rules are',
     'IDENTICAL to RAW. The RAW verdict is kept in every table below — it is not replaced.', '',
     '## Per clip (worst value over the clip; ✔ = inside the approved envelope)', '',
     '| Clip | RAW / VISIBLE (G2 → G2.1) | paw-in-head mm | scarf-in-head mm (count) | scarf-in-body | arm stretch L / R | body stretch | leg stretch raw (visible) | foot slide mm/f | start/end or seam (°/mm) | remaining failures |',
     '|---|---|---|---|---|---|---|---|---|---|---|']
for n, c in M21.items():
    o = M20[n]; e1, e0 = E21['clips'][n], E20['clips'][n]
    v = lambda d, k: d['stretch_p99_max'].get(k)
    leg = lambda d: f"{max(d['stretch_p99_max'].get('FOX_Leg_L', 0), d['stretch_p99_max'].get('FOX_Leg_R', 0))} ({max(d.get('vis_stretch_p99_max', {}).get('FOX_Leg_L', 0), d.get('vis_stretch_p99_max', {}).get('FOX_Leg_R', 0))})"
    pose = c.get('rest_match') or c.get('loop_seam')
    ps = f"{max(pose['start_deg/mm'] + pose['end_deg/mm'])}" if 'start_deg/mm' in pose else f"{max(pose['pose_diff_deg'], pose['pose_diff_mm'])}"
    rem = [f"{f['metric'].replace('stretch_p99_max.', '')} {f['g2_1']}>{f['approved_max']}" for f in e1['raw_failures']] + [h for h, ok in e1['hard_rules'].items() if not ok]
    fs = lambda d: (d.get('foot_slide_mm_per_frame') or {}).get('max')
    L.append(f"| {n} | {'✔' if e0['raw_pass'] else '✘'}/{'✔' if e0['visible_pass'] else '✘'} → **{'✔' if e1['raw_pass'] else '✘'}/{'✔' if e1['visible_pass'] else '✘'}** | {o.get('arm_in_head_max_depth_mm', 0)} → {c.get('arm_in_head_max_depth_mm', 0)} "
             f"| {o.get('scarf_in_head_max_depth_mm', 0)} ({o['scarf_new_in_head']}) → {c.get('scarf_in_head_max_depth_mm', 0)} ({c['scarf_new_in_head']}) | {o['scarf_new_in_body']} → {c['scarf_new_in_body']} "
             f"| {v(o, 'FOX_Arm_L')}/{v(o, 'FOX_Arm_R')} → {v(c, 'FOX_Arm_L')}/{v(c, 'FOX_Arm_R')} | {v(o, 'FOX_Body')} → {v(c, 'FOX_Body')} | {leg(o)} → {leg(c)} | {fs(o)} → {fs(c)} | {ps} | {'; '.join(rem) or '—'} |")
env = E21['raw_envelope']
L += ['', f"Approved limits: paw-in-head {env.get('arm_in_head_max_depth_mm')} mm / {env.get('arm_new_in_head')} vertices · scarf-in-head {env.get('scarf_in_head_max_depth_mm')} mm / {env.get('scarf_new_in_head')} vertices · arm stretch {env.get('stretch_p99_max.FOX_Arm_#')} · body {env.get('stretch_p99_max.FOX_Body')} · leg {env.get('stretch_p99_max.FOX_#eg_#', env.get('stretch_p99_max.FOX_Leg_#'))} · foot slide 0.05 mm/frame on standing frames.", '',
      '## Foot contact — world-space trace (`foot_trace_g2_1.py`)', '', 'Sole positions are measured in world space every frame (not inferred from clip endpoints); slide = horizontal travel of a sole that is in contact on two consecutive frames while the fox stands.', '',
      '| Clip | G2 max slide L / R (mm/frame) | G2.1 max slide L / R (mm/frame) | anim_check per-vertex max (G2.1) |', '|---|---|---|---|']
for cl in FT['G2.1']:
    a, b = FT['G2'][cl]['max_slide_standing_mm_per_frame'], FT['G2.1'][cl]['max_slide_standing_mm_per_frame']
    L.append(f"| {cl} | {a['L']:.2f} / {a['R']:.2f} | {b['L']:.3f} / {b['R']:.3f} | {(M21[cl].get('foot_slide_mm_per_frame') or {}).get('max')} |")
L += ['', 'Plots: `closeups/foot_trace_<clip>.png` (sole world y per frame, contact frames dotted, G2 left / G2.1 right).', '',
      '## Resolver (`anim_g2_1.py`)', '', 'Frames violating an approved limit before / after, and the smallest factor applied to each channel group (1 = untouched; the resolver never goes below 0.6, i.e. ≥ 60 % of a gesture is kept):', '',
      '| Clip | violating frames | min factor per group | still over the resolver margin |', '|---|---|---|---|']
for n, r in SPEC['resolver'].items():
    L.append(f"| {n} | {r['violating_frames_before']} → {r['violating_frames_after']} | {r['min_factor'] or '—'} | {r['unresolved'] or '—'} |")
L += ['', '## glTF pose fidelity', '', f"G2.1 module vs Blender worst **{FID['g2_1_module_vs_blender']['worst']['max_mm']} mm** at {FID['g2_1_module_vs_blender']['worst']['at']} (tolerance 6.0 mm, same as G1.1 / G2; approved E2 GLB: {FID['e2_approved_glb_vs_blender']['worst']['max_mm']} mm)."]
open(P('08_VALIDATION', 'deformation_report_g2_1.md'), 'w').write('\n'.join(L) + '\n')

RT = J('08_VALIDATION', 'runtime_g2_1', 'g2_1_runtime_report.json')
REG = J('08_VALIDATION', 'runtime_g2_1', 'regressions_g2_1.json') if os.path.exists(P('08_VALIDATION', 'runtime_g2_1', 'regressions_g2_1.json')) else {}
R = ['# Gate G2.1 — runtime validation & regression report', '', f"Generated by `make_reports_g2_1.py`. Headless Chrome with a CPU rasteriser (llvmpipe / SwiftShader): no GPU timing claimed.", '',
     f"## G2.1 browser suite (`browser_g2_1_test.py`, G2.1 module in the versioned sandbox `companion_sandbox_g2_1`): **{RT['summary']}**", '',
     'Covers GLB track binding (every track of the G2.1 module binds to the E2 Fox), facial morph compatibility (morph values = Blender ≤ 0.002), pose equivalence ≤ 0.05 mm vs the module\'s own glTF data, format fidelity ≤ 6 mm vs Blender, the five round trips with a pop detector, interruptions and recovery, priorities, interactions, prop / VFX cleanup (renderer resources stable over repeated passes), Lv1 / Lv30 scaling, dispose and the missing-module fallbacks.', '',
     '| Check | Result |', '|---|---|'] + [f"| {c['name']} | {'PASS' if c['pass'] else 'FAIL'} |" for c in RT['checks']]
if REG:
    R += ['', '## Regressions of the approved suites against the G2.1 runtime (`regress_g2_1.py`, assertions unchanged)', '', '| Suite | Script | Build / URL | Result |', '|---|---|---|---|']
    for k, v in REG.items():
        res = v['summary'][-1] if v['summary'] and 'PASS' in v['summary'][-1] else f"exit {v['exit']}"
        if k == 'e2':
            e2 = J('08_VALIDATION', 'runtime_g2_1', 'regress_e2', 'anim_runtime_report_e2.json'); t = e2['page_checks'] + e2['interaction_tests']
            res = f"{sum(x['status'] == 'PASS' for x in t)}/{len(t)} PASS"
        if k == 'flame_g1_1':
            fl = J('08_VALIDATION', 'runtime_g2_1', 'regress_flame_g1_1', 'flame_attachment_g1_1.json'); res = f"exit {v['exit']} · max attach err Lv1 {fl['lv1']['max_attach_err_mm']} mm, Lv30 {fl['lv30']['max_attach_err_mm']} mm"
        R.append(f"| {k} | `{v['script']} {' '.join(a for a in v['args'] if not a.startswith('/'))}` | {v['url']} | {res} |")
open(P('08_VALIDATION', 'gate_g2_1_runtime_report.md'), 'w').write('\n'.join(R) + '\n')
print('ok', RT['summary'], 'raw', cnt(E21, 'raw_pass'), 'vis', cnt(E21, 'visible_pass'))
